1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
15: 
16:   late final AnimationController _fadeController;
17: 
18:   late Future<List<CurrencyModel>> _currencyListFuture;
19: 
20:   List<CurrencyModel> _allCurrencies = [];
21: 
22:   @override
23:   void initState() {
24:     super.initState();
25:     _initAnimation();
26:     _initData();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _filteredCurrenciesNotifier.dispose();
32:     _fadeController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _fadeController = AnimationController(
38:       duration: Duration(milliseconds: 400),
39:       vsync: this,
40:     );
41:   }
42: 
43:   void _initData() {
44:     final currencyRepository = context.read<CurrencyRepository>();
45: 
46:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest()).then((CurrencyPage page) {
47:       final List<CurrencyModel> value = page.items;
48:       _allCurrencies = value;
49:       _filteredCurrenciesNotifier = ValueNotifier(value);
50: 
51:       _fadeController.forward(); // запускаем анимацию
52: 
53:       currencyRepository.saveCurrencyList(value);
54: 
55:       return value;
56:     });
57:   }
58: 
59:   void _filterCurrencies(String query) {
60:     final String lowerQuery = query.toLowerCase();
61:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
62:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
63:     });
64: 
65:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
66:   }
67: 
68:   @override
69:   Widget build(BuildContext context) {
70:     return Scaffold(
71:       appBar: AppBar(title: Text(context.loc.currencyRate)),
72:       body: FutureBuilder(
73:         future: _currencyListFuture,
74:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
75:           final List<CurrencyModel>? data = snapshot.data;
76:           if (data == null) return const SizedBox.shrink();
77: 
78:           return FadeTransition(
79:             opacity: _fadeController.view,
80:             child: Column(
81:               children: [
82:                 Padding(
83:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
84:                   child: SearchView(onChanged: _filterCurrencies),
85:                 ),
86:                 Expanded(
87:                   child: ValueListenableBuilder<List<CurrencyModel>>(
88:                     valueListenable: _filteredCurrenciesNotifier,
89:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
90:                       return ListView.builder(
91:                         itemCount: data.length,
92:                         itemBuilder: (BuildContext context, int index) {
93:                           final CurrencyModel currency = data[index];
94: 
95:                           return Padding(
96:                             key: ValueKey(currency.id),
97:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
98:                             child: CurrencyCard(model: currency),
99:                           );
100:                         },
101:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
102:                       );
103:                     },
104:                   ),
105:                 ),
106:               ],
107:             ),
108:           );
109:         },
110:       ),
111:     );
112:   }
113: }

1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/model/currency_model.dart';
3: 
4: enum PriceChange {
5:   up,
6:   down,
7:   stable;
8: }
9: 
10: class CurrencyCard extends StatelessWidget {
11:   const CurrencyCard({super.key, required this.model});
12: 
13:   final CurrencyModel model;
14: 
15:   static final _tweenAnimation = Tween<Offset>(begin: Offset(1.0, 0.0), end: Offset.zero);
16: 
17:   @override
18:   Widget build(BuildContext context) {
19:     final PriceChange priceChange = model.asPriceChange;
20:     final ThemeFonts fonts = context.fonts;
21:     final ThemeColors colors = context.colors;
22: 
23:     return GestureDetector(
24:       onTap: () {
25:         Navigator.push(
26:           context,
27:           PageRouteBuilder(
28:             pageBuilder: (BuildContext context, Animation<double> animation, Animation<double> secondaryAnimation) {
29:               return CurrencyDetailPage(title: model.name);
30:             },
31:             transitionsBuilder: (context, animation, secondaryAnimation, child) {
32:               const Cubic curve = Curves.ease;
33: 
34:               final Animatable<Offset> tween = _tweenAnimation.chain(CurveTween(curve: curve));
35:               final Animation<Offset> offsetAnimation = animation.drive(tween);
36: 
37:               return SlideTransition(position: offsetAnimation, child: child);
38:             },
39:           ),
40:         );
41:       },
42:       child: Container(
43:         padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 8),
44:         decoration: BoxDecoration(
45:           color: colors.cardColor,
46:           borderRadius: BorderRadius.circular(12),
47:         ),
48:         child: Row(
49:           children: [
50:             CurrencyIcon(title: model.symbol),
51:             Expanded(
52:               child: Padding(
53:                 padding: const EdgeInsets.symmetric(horizontal: 6),
54:                 child: Text(
55:                   model.name,
56:                   style: fonts.semiBold12,
57:                 ),
58:               ),
59:             ),
60:             Text(
61:               model.value.toStringAsFixed(2),
62:               style: fonts.semiBold12.copyWith(
63:                 color: switch (priceChange) {
64:                   PriceChange.up => colors.greenWrasse,
65:                   PriceChange.down => colors.red,
66:                   PriceChange.stable => colors.stormyGrey,
67:                 },
68:               ),
69:             ),
70:             Padding(
71:               padding: const EdgeInsets.only(left: 4, right: 6),
72:               child: Text(
73:                 context.loc.asNominal(model.nominal),
74:                 style: fonts.regular12,
75:               ),
76:             ),
77:             Image.asset(
78:               switch (priceChange) {
79:                 PriceChange.up => 'assets/icons/arrow_up.png',
80:                 PriceChange.down => 'assets/icons/arrow_down.png',
81:                 PriceChange.stable => 'assets/icons/arrow_up.png',
82:               },
83:               width: 10,
84:               height: 10,
85:             ),
86:           ],
87:         ),
88:       ),
89:     );
90:   }
91: }
92: 
93: class CurrencyIcon extends StatelessWidget {
94:   const CurrencyIcon({super.key, required this.title});
95: 
96:   final String title;
97: 
98:   @override
99:   Widget build(BuildContext context) {
100:     return Container(
101:       constraints: BoxConstraints.tight(Size.square(40)),
102:       decoration: BoxDecoration(
103:         color: context.colors.currencyCardSymbolBackground,
104:         shape: BoxShape.circle,
105:       ),
106:       child: Center(
107:         child: Text(
108:           title,
109:           style: context.fonts.semiBold12.copyWith(color: Colors.white),
110:         ),
111:       ),
112:     );
113:   }
114: }
115: 
116: extension on CurrencyModel {
117:   PriceChange get asPriceChange {
118:     if (value > previousValue) return PriceChange.up;
119:     if (value < previousValue) return PriceChange.down;
120: 
121:     return PriceChange.stable;
122:   }
123: }

