1: import 'package:flutter_test/flutter_test.dart';
2: import 'package:intl/date_symbol_data_local.dart';
3: import 'package:mad_flutter_practicum/app/app.dart';
4: import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
5: import 'package:mad_flutter_practicum/domain/domain.dart';
6: import 'package:mockito/mockito.dart';
7: 
8: import '../mocks/repository.mocks.dart';
9: 
10: import 'widget.dart';
11: 
12: Future<void> main() async {
13:   await initializeDateFormatting(AppConstants.ruLocale, null);
14: 
15:   group('CurrencyListPage', () {
16:     final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
17: 
18:     final currencyItems = [
19:       CurrencyModel(
20:         id: '1',
21:         nominal: 1,
22:         name: 'Доллар США',
23:         symbol: 'USD',
24:         value: 78.4181,
25:         previousValue: 78.5,
26:       ),
27:       CurrencyModel(
28:         id: '2',
29:         nominal: 1,
30:         name: 'Евро',
31:         symbol: 'EUR',
32:         value: 92.7440,
33:         previousValue: 92.2,
34:       ),
35:     ];
36: 
37:     setUp(() {
38:       when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
39:       when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
40:     });
41: 
42:     testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
43:       await tester.pumpWidget(
44:         buildWidget(
45:           providers: [
46:             Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
47:           ],
48:           child: CurrencyListPage(),
49:         ),
50:       );
51: 
52:       await tester.pumpAndSettle();
53: 
54:       expect(find.text('USD'), findsOneWidget);
55:       expect(find.text('EUR'), findsOneWidget);
56:       expect(find.text('JPY'), findsNothing);
57:       expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
58:     });
59: 
60:     testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
61:       await tester.pumpWidget(
62:         buildWidget(
63:           providers: [
64:             Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
65:           ],
66:           child: const CurrencyListPage(),
67:         ),
68:       );
69: 
70:       await tester.pumpAndSettle();
71:       await tester.tap(find.byType(CurrencyCard).first);
72:       await tester.pumpAndSettle();
73: 
74:       expect(find.byType(CurrencyDetailPage), findsOneWidget);
75:     });
76: 
77:     testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
78:       await tester.pumpWidget(
79:         buildWidget(
80:           providers: [
81:             Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
82:           ],
83:           child: const CurrencyListPage(),
84:         ),
85:       );
86: 
87:       await tester.pumpAndSettle();
88:       await tester.enterText(find.byType(TextField), 'Евро');
89:       await tester.pump();
90: 
91:       expect(find.byType(CurrencyCard), findsOneWidget);
92:     });
93:   });
94: }

