                    child: CircularProgressIndicator(strokeWidth: 2),
                  )
                else if (_hasMore && !_isLoadingMore)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 20),
                    child: TextButton(
                      onPressed: _loadMore,
                      child: Text(context.loc.showMore),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}
